import { PlaneGeometry, Mesh, MeshBasicNodeMaterial } from 'three/webgpu';

export default function createNode(config, ctx) {
  const { imageUrl } = config;
  const aspect = 512 / 320; // from atlas region hint
  const width = 2.0;
  const height = width / aspect; // ~1.25

  const geometry = new PlaneGeometry(width, height);
  const material = new MeshBasicNodeMaterial({
    color: 0xffffff,
    transparent: true,
  });

  const mesh = new Mesh(geometry, material);
  mesh.position.set(-3.2, -0.3, 0); // from scene placement
  mesh.rotation.set(0, 0, 0);
  mesh.scale.set(1, 1, 1);

  // Event handlers – empty for this static card
  mesh.userData.handlers = {};

  // Async texture load (cached by ctx.textureLoader)
  if (imageUrl) {
    ctx.textureLoader.loadTexture(imageUrl).then((tex) => {
      material.map = tex;
      material.needsUpdate = true;
    });
  }

  // Cleanup – dispose geometry, material, and any loaded textures
  mesh.userData.cleanup = () => {
    geometry.dispose();
    if (material.map) {
      material.map.dispose();
    }
    material.dispose();
    // No GSAP timelines or primitives to kill
  };

  return mesh;
}
